-- Generated by packages/db/scripts/emit-estimated-portions.ts --function from the estimate table in @keylow/core. Do not edit by hand.
-- Regenerate with: pnpm --filter @keylow/db emit:estimated-portions --function supabase/migrations/<timestamp>_give_foods_default_portions.sql
-- A change to the estimate table is a new generated migration that replaces this function, and an applied migration is never edited.
-- The function runs the statements of the estimated portions migration. A bulk import calls it with the ids of the foods it wrote, so each ends on exactly one default and no other food is touched. With no ids it covers every food. A food that already has a default keeps it, and nothing is deleted.
create or replace function public.give_foods_default_portions(p_food_ids uuid[] default null)
returns void
language plpgsql
security definer
set search_path = ''
set row_security = off
as $body$
begin
-- 1. A food of any source that has portions and no default opens on its first portion, the one with the lowest position. It gets no extra row.
update public.food_portions portion
set is_default = true
from (
  select distinct on (candidate.food_id) candidate.id
  from public.food_portions candidate
  where not exists (select 1 from public.food_portions existing where existing.food_id = candidate.food_id and existing.is_default) and (p_food_ids is null or candidate.food_id = any (p_food_ids))
  order by candidate.food_id, candidate.position, candidate.id
) first_portion
where portion.id = first_portion.id;

-- 2. A shared default whose label is only a measure, such as 240 g, reads as 1 serving. The size is unchanged and a person's own label is left alone.
update public.food_portions
set label = '1 serving'
where owner_id is null and is_default and label ~* '^~?\s*\d+(?:[.,]\d+)?\s*(?:kgs?|mgs?|g|gr|grm|grs|grms|gm|gms|grams?|grammes?|ml|mls|cl|dl|l|ltr|litres?|liters?|oz|fl\.?\s?oz)\.?\s*$' and (p_food_ids is null or food_id = any (p_food_ids));

-- 3. A CoFID food with no default gets the row of its food group. The group is its first one or two letters, matched exactly.
insert into public.food_portions (food_id, owner_id, label, grams, ml, is_default, position)
select food.id, food.owner_id, estimate.label, case when food.basis = 'per_100g' then case when food.kcal >= 250 then estimate.dry_size else estimate.cooked_size end end, case when food.basis = 'per_100ml' then case when food.kcal >= 250 then estimate.dry_size else estimate.cooked_size end end, true, coalesce((select max(existing.position) + 1 from public.food_portions existing where existing.food_id = food.id), 0)
from public.foods food
join (values
  ('MB', '1 typical burger', 200, 200),
  ('AB', '1 typical sandwich', 200, 200),
  ('AE', '1 typical serving', 150, 150),
  ('AG', '1 typical roll', 60, 60),
  ('AF', '1 typical serving', 50, 50),
  ('AM', '1 typical biscuit', 15, 15),
  ('AK', '1 typical biscuit', 15, 15),
  ('AI', '1 typical serving', 40, 40),
  ('AC', '1 typical serving', 75, 180),
  ('AD', '1 typical serving', 75, 180),
  ('AT', '1 typical serving', 75, 180),
  ('AA', '1 typical serving', 30, 30),
  ('AN', '1 typical serving', 70, 70),
  ('AS', '1 typical serving', 120, 120),
  ('BR', '1 typical serving', 120, 120),
  ('AP', '1 typical serving', 60, 60),
  ('AO', '1 typical serving', 60, 60),
  ('BA', '1 typical glass', 200, 200),
  ('BC', '1 typical glass', 200, 200),
  ('BH', '1 typical glass', 200, 200),
  ('BJ', '1 typical serving', 30, 30),
  ('BL', '1 typical serving', 30, 30),
  ('BN', '1 typical serving', 125, 125),
  ('BP', '1 typical serving', 75, 75),
  ('BV', '1 typical serving', 150, 150),
  ('CD', '1 typical serving', 150, 150),
  ('DA', '1 typical serving', 180, 180),
  ('DB', '1 typical serving', 60, 120),
  ('DF', '1 typical serving', 80, 80),
  ('DG', '1 typical serving', 80, 80),
  ('F', '1 typical serving', 80, 80),
  ('FA', '1 typical serving', 80, 80),
  ('DI', '1 typical serving', 20, 20),
  ('DR', '1 typical serving', 250, 250),
  ('FC', '1 typical glass', 200, 200),
  ('PC', '1 typical glass', 200, 200),
  ('PE', '1 typical glass', 200, 200),
  ('G', '1 typical serving', 30, 30),
  ('GA', '1 typical serving', 30, 30),
  ('H', '1 typical serving', 2, 2),
  ('J', '1 typical serving', 140, 140),
  ('JA', '1 typical serving', 140, 140),
  ('JC', '1 typical serving', 140, 140),
  ('JR', '1 typical serving', 140, 140),
  ('JK', '1 typical serving', 80, 80),
  ('JM', '1 typical serving', 80, 80),
  ('MA', '1 typical serving', 150, 150),
  ('MC', '1 typical serving', 150, 150),
  ('ME', '1 typical serving', 150, 150),
  ('MG', '1 typical serving', 150, 150),
  ('MI', '1 typical serving', 100, 100),
  ('MR', '1 typical serving', 300, 300),
  ('OA', '1 typical serving', 10, 10),
  ('OB', '1 typical serving', 10, 10),
  ('OC', '1 typical serving', 10, 10),
  ('OE', '1 typical serving', 10, 10),
  ('OF', '1 typical serving', 10, 10),
  ('BT', '1 typical serving', 10, 10),
  ('P', '1 typical cup', 200, 200),
  ('PA', '1 typical cup', 200, 200),
  ('QA', '1 typical glass', 330, 330),
  ('QC', '1 typical glass', 330, 330),
  ('Q', '1 typical glass', 330, 330),
  ('QE', '1 typical glass', 175, 175),
  ('QF', '1 typical glass', 50, 50),
  ('QG', '1 typical glass', 50, 50),
  ('QI', '1 typical serving', 25, 25),
  ('QK', '1 typical serving', 25, 25),
  ('S', '1 typical serving', 15, 15),
  ('SC', '1 typical serving', 15, 15),
  ('SE', '1 typical serving', 40, 40),
  ('SN', '1 typical serving', 30, 30),
  ('WA', '1 typical serving', 300, 300),
  ('WC', '1 typical serving', 20, 20),
  ('WE', '1 typical serving', 20, 20),
  ('WY', '1 typical serving', 5, 5)
) as estimate (food_group, label, dry_size, cooked_size) on estimate.food_group = substring(upper(btrim(food.food_group)) from '^[A-Z]{1,2}')
where food.source = 'cofid' and not exists (select 1 from public.food_portions existing where existing.food_id = food.id and existing.is_default) and (p_food_ids is null or food.id = any (p_food_ids))
on conflict (food_id) where is_default do nothing;

-- 4. Any food with no portions at all, of any source and including a person's own, gets the row for its energy. The size is in grams or millilitres by the food's basis. A food per portion is the exception, because it has a count portion of its own.
insert into public.food_portions (food_id, owner_id, label, grams, ml, is_default, position)
select food.id, food.owner_id, '1 typical serving', case when food.basis = 'per_100g' then coalesce(band.size, 100) end, case when food.basis = 'per_100ml' then coalesce(band.size, 100) end, true, coalesce((select max(existing.position) + 1 from public.food_portions existing where existing.food_id = food.id), 0)
from public.foods food
left join lateral (
  select band.size from (values
    ('per_100g', 0, 5),
    ('per_100g', 5, 80),
    ('per_100g', 60, 150),
    ('per_100g', 150, 100),
    ('per_100g', 300, 40),
    ('per_100g', 450, 30),
    ('per_100g', 700, 15),
    ('per_100ml', 0, 200),
    ('per_100ml', 100, 30),
    ('per_100ml', 500, 15)
  ) as band (basis, lower_bound, size)
  where band.basis = food.basis::text and food.kcal >= band.lower_bound
  order by band.lower_bound desc limit 1
) band on true
where food.basis <> 'per_portion' and not exists (select 1 from public.food_portions existing where existing.food_id = food.id and existing.is_default) and (p_food_ids is null or food.id = any (p_food_ids))
on conflict (food_id) where is_default do nothing;
end;
$body$;

revoke execute on function public.give_foods_default_portions(uuid[]) from public, anon, authenticated;
grant execute on function public.give_foods_default_portions(uuid[]) to service_role;
